orders = {101: {"owner": "alice", "dest": "서울역"}, 102: {"owner": "bob", "dest": "강남역"}}
def get_order_bad(user, oid):
    return orders[oid]
def get_order_good(user, oid):
    o = orders.get(oid)
    if o is None or o["owner"] != user:
        return "403 Forbidden"
    return o
print(get_order_bad("alice", 102))   # {'owner': 'bob', 'dest': '강남역'}
print(get_order_good("alice", 102))  # 403 Forbidden
print(get_order_good("alice", 101))  # {'owner': 'alice', 'dest': '서울역'}

import json
policy = json.loads('''{"Statement":[
 {"Effect":"Allow","Principal":"*","Action":"s3:GetObject","Resource":"arn:aws:s3:::demo-assets/*"},
 {"Effect":"Allow","Principal":{"AWS":"arn:aws:iam::111122223333:role/app"},"Action":"s3:*","Resource":"*"}
]}''')
for i, st in enumerate(policy["Statement"]):
    p = st.get("Principal")
    public = p == "*" or (isinstance(p, dict) and p.get("AWS") == "*")
    acts = st["Action"] if isinstance(st["Action"], list) else [st["Action"]]
    wild = any(a.endswith(":*") or a == "*" for a in acts) or st.get("Resource") == "*"
    print(i, "누구나 접근" if public else "특정 주체", "| 권한 과다" if wild else "| 권한 좁음")
# 0 누구나 접근 | 권한 좁음
# 1 특정 주체 | 권한 과다

vulns = [
    ("CVE-A", 9.8, 0.02, False, "internal"),
    ("CVE-B", 7.5, 0.91, True,  "internet"),
    ("CVE-C", 5.3, 0.40, False, "internet"),
    ("CVE-D", 9.1, 0.001, False, "internal"),
]
def due_days(cvss, epss, kev, exposure):
    if kev or (epss >= 0.5 and exposure == "internet"):
        return 7
    if cvss >= 9.0 or epss >= 0.1:
        return 30
    if cvss >= 7.0:
        return 60
    return 90
for cve, cvss, epss, kev, exp in sorted(vulns, key=lambda v: due_days(*v[1:])):
    print(cve, cvss, epss, kev, exp, "->", due_days(cvss, epss, kev, exp), "일")
# CVE-B 7.5 0.91 True internet -> 7 일
# CVE-A 9.8 0.02 False internal -> 30 일
# CVE-C 5.3 0.4 False internet -> 30 일
# CVE-D 9.1 0.001 False internal -> 30 일
